/**
 * HUD, cockpit and text pictures traced from the vector ROM of the original
 * 1983 Atari Star Wars arcade game. Data only. All coordinates are vector
 * generator screen units, +X right, +Y up, origin at the screen centre unless
 * stated. Do not edit the numbers by hand.
 */

export interface Stroke {
  readonly color: string;
  readonly lum: number;
  readonly intensity: number;
  readonly points: readonly (readonly [number, number])[];
}

